<template><div class="page fade-up"><div class="head-links"><router-link :to="`/projects/${id}/story-bible`" class="back">← 故事圣经</router-link></div><div class="page-head"><div><h1>分集改编规划</h1><p class="sub">把原文章节和关键事件映射为约 180 秒、25 镜的单集。</p></div><button class="btn" :disabled="busy" @click="generate">生成分集映射</button></div><div v-if="error" class="card error">{{error}}</div><section class="card strategy"><h2>改编策略</h2><div class="grid"><label>模式<select v-model="strategy.mode" class="input"><option value="faithful">忠实改编</option><option value="cinematic">影视化改编</option><option value="爽剧强化">爽剧强化</option><option value="free">自由改编</option></select></label><label>目标集数<input v-model.number="strategy.target_episodes" type="number" min="1" max="200" class="input"></label><label>每集秒数<input v-model.number="strategy.target_duration" type="number" min="60" max="600" class="input"></label><label>每集镜头<input v-model.number="strategy.target_scenes" type="number" min="10" max="50" class="input"></label></div><button class="btn btn-secondary" @click="saveStrategy">保存策略</button></section><section class="episodes"><article v-for="ep in episodes" :key="ep.episode_n" class="card episode"><header><h3>第{{ep.episode_n}}集 · {{ep.title}}</h3><span class="badge">{{ep.status}}</span></header><p>章节 {{ep.chapter_start}}～{{ep.chapter_end}} · {{ep.target_duration}}秒 / {{ep.target_scenes}}镜</p><p>{{ep.adaptation_goal}}</p><p><b>钩子：</b>{{ep.hook}}</p><p><b>连续性：</b>{{ep.continuity_status||'pending'}}</p><div class="actions"><button class="btn btn-sm btn-secondary" :disabled="busy||ep.status!=='draft'" @click="approve(ep)">审核映射</button><button class="btn btn-sm" :disabled="busy||ep.status!=='approved'" @click="script(ep)">生成剧本与分镜</button><button class="btn btn-sm btn-secondary" :disabled="busy||!ep.script" @click="review(ep)">连续性复审</button></div><details v-if="ep.script"><summary>查看改编剧本</summary><pre>{{ep.script}}</pre></details></article></section></div></template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{api}from'../api';const id=useRoute().params.id,busy=ref(false),error=ref(''),episodes=ref([]),strategy=reactive({mode:'cinematic',target_episodes:10,target_duration:180,target_scenes:25,chapter_start:1,chapter_end:0});async function load(){try{episodes.value=(await api.adaptations(id)).data.adaptations||[];try{Object.assign(strategy,(await api.adaptationStrategy(id)).data)}catch(e){if(e.response?.status!==404)throw e}}catch(e){error.value=e.response?.data?.error||e.message}}async function run(fn){busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=e.response?.data?.error||e.message}finally{busy.value=false}}const saveStrategy=()=>run(()=>api.saveAdaptationStrategy(id,strategy));const generate=()=>run(()=>api.generateAdaptations(id));const approve=ep=>run(()=>api.approveAdaptation(id,ep.episode_n));const script=ep=>run(()=>api.generateAdaptationScript(id,ep.episode_n));const review=ep=>run(()=>api.reviewAdaptation(id,ep.episode_n));onMounted(load)
</script><style scoped>.page-head{display:flex;justify-content:space-between;gap:16px}.strategy{padding:20px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.grid label{display:grid;gap:7px}.episodes{display:grid;gap:14px}.episode{padding:18px}.episode header,.actions{display:flex;justify-content:space-between;gap:10px;align-items:center}.actions{justify-content:flex-start;flex-wrap:wrap}.episode pre{white-space:pre-wrap;max-height:400px;overflow:auto}.error{padding:15px;color:var(--red)}@media(max-width:760px){.grid{grid-template-columns:1fr 1fr}.page-head{display:block}}@media(max-width:480px){.grid{grid-template-columns:1fr}}</style>